import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))
    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            if out and out[-1] != '-':
                out.append('-')
    if out and out[-1] == '-':
        out.pop()
    return ''.join(out)

import unicodedata


def slugify(s):
    # Decompose so accented letters (e.g. 'õ') break into an ASCII base
    # plus a combining mark, then drop anything that isn't ASCII so only
    # plain letters/digits survive.
    s = unicodedata.normalize('NFKD', s).lower()
    s = ''.join(ch for ch in s if ch.isascii())

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')
